/// Lazily initialized per-language table of compiled queries.
///
/// Each language gets its own [`OnceLock`] so only the language actually parsed
/// is compiled, on first use, outside a global lock (OnceLock guarantees
/// at-most-once initialization per language, holding only that language's
/// initialization lock during compilation).
type QueryEntry = OnceLock<Result<CompiledQueries, ParserError>>;

static QUERY_CACHE: LazyLock<Vec<(&'static str, QueryEntry)>> = LazyLock::new(|| {
    crate::lang::supported_languages()
        .iter()
        .map(|name| (*name, OnceLock::new()))
        .collect()
});

/// Test-only per-language count of query-compilation attempts (at most one
/// per language). Keyed per language so tests asserting on one language are
/// isolated from parallel tests compiling other languages.
#[cfg(test)]
static COMPILE_COUNTS: std::sync::LazyLock<
    std::sync::Mutex<std::collections::HashMap<&'static str, usize>>,
> = std::sync::LazyLock::new(|| std::sync::Mutex::new(std::collections::HashMap::new()));

#[cfg(test)]
fn compile_count(language: &str) -> usize {
    COMPILE_COUNTS
        .lock()
        .expect("compile-count map lock")
        .get(language)
        .copied()
        .unwrap_or(0)
}

/// Get compiled queries for a language, compiling on first use of that language.
///
/// Excluded from coverage: the `Err` arm is unreachable because `build_compiled_queries`
/// only fails on invalid hardcoded query strings.
#[cfg_attr(coverage_nightly, coverage(off))]
fn get_compiled_queries(language: &str) -> Result<&'static CompiledQueries, ParserError> {
    let (entry, _lang_name) = QUERY_CACHE
        .iter()
        .find(|(name, _)| *name == language)
        .map(|(name, entry)| (entry, name))
        .ok_or_else(|| ParserError::UnsupportedLanguage(language.to_string()))?;
    let result = entry.get_or_init(|| {
        #[cfg(test)]
        COMPILE_COUNTS
            .lock()
            .expect("compile-count map lock")
            .entry(_lang_name)
            .and_modify(|c| *c += 1)
            .or_insert(1);
        // Failure is logged here, inside the at-most-once initializer, preserving
        // the log-once semantics of the former eager cache.
        match get_language_info(language) {
            Some(lang_info) => match build_compiled_queries(&lang_info) {
                Ok(compiled) => Ok(compiled),
                Err(e) => {
                    // At-most-once failure log: the initializer runs once per
                    // language, preserving the eager cache's log-once semantics.
                    tracing::error!("Failed to compile queries for language {}: {}", language, e);
                    Err(e)
                }
            },
            None => Err(ParserError::UnsupportedLanguage(language.to_string())),
        }
    });
    match result {
        Ok(compiled) => Ok(compiled),
        Err(_) => Err(ParserError::UnsupportedLanguage(language.to_string())),
    }
}

thread_local! {
    pub(crate) static PARSER: RefCell<Parser> = RefCell::new(Parser::new());
    pub(crate) static QUERY_CURSOR: RefCell<QueryCursor> = RefCell::new(QueryCursor::new());
}

/// Shared language-resolution and parse prologue with pre/post deadline checks.
fn parse_with_deadline(
    source: &str,
    language: &str,
    tc: TimeoutConfig,
) -> Result<(Tree, crate::languages::LanguageInfo), ParserError> {
    // Check deadline at the start before any parsing work.
    if tc.is_exceeded() {
        return Err(ParserError::Timeout(tc.micros));
    }

    let (tree, lang_info) = resolve_and_parse(source, language)?;

    // Check deadline after parsing
    if tc.is_exceeded() {
        return Err(ParserError::Timeout(tc.micros));
    }

    Ok((tree, lang_info))
}

/// Resolve `language` to its tree-sitter grammar and parse `source` with the
/// shared thread-local parser. Returns the parse tree plus resolved language info.
fn resolve_and_parse(
    source: &str,
    language: &str,
) -> Result<(Tree, crate::languages::LanguageInfo), ParserError> {
    let lang_info = get_language_info(language)
        .ok_or_else(|| ParserError::UnsupportedLanguage(language.to_string()))?;

    let tree = PARSER.with(|p| {
        let mut parser = p.borrow_mut();
        parser
            .set_language(&lang_info.language)
            .map_err(|e| ParserError::ParseError(format!("Failed to set language: {e}")))?;
        parser
            .parse(source, None)
            .ok_or_else(|| ParserError::ParseError("Failed to parse".to_string()))
    })?;

